/* Stronger: self-contained offline-first workout journal. No network libraries. */
'use strict';
const LIBRARY = {
 A: [
  {id:'goblet',name:'Goblet squat',sets:3,target:'8–10',qtyUnit:'reps',rest:150,tempo:'3–1–1',how:'Hold a dumbbell against the chest. Brace, sit between your hips over three seconds, pause briefly, and stand with whole feet planted.',watch:'Keep your neck neutral. Avoid heels lifting, knees collapsing inward, or lumbar rounding.',modify:'Leg press if a front-held weight irritates your neck or back.'},
  {id:'dbbench',name:'Neutral-grip DB bench press',sets:3,target:'8–10',qtyUnit:'reps',rest:120,tempo:'2–1–1',how:'Lie with head supported and feet flat. Keep palms facing each other and elbows comfortably close to your torso. Lower in control; press smoothly.',watch:'Do not drive your head into the bench, flare elbows aggressively, or force a painful range.',modify:'Chest press machine with supported head and back.'},
  {id:'chestrow',name:'Chest-supported row',sets:3,target:'10–12',qtyUnit:'reps',rest:105,tempo:'2–1–2',how:'Rest your torso on an incline bench. Row elbows toward your lower ribs, pause, then lower the weights under control.',watch:'Do not crane your neck or lift your torso to cheat.',modify:'Chest-supported row machine or supported cable row.'},
  {id:'hamcurl',name:'Seated hamstring curl',sets:2,target:'10–12',qtyUnit:'reps',rest:90,tempo:'2–1–3',how:'Align your knees with the machine pivot. Curl the pad with control, pause, and return slowly.',watch:'Keep hips and back against the pad. Avoid painful pulling behind the knees.',modify:'Lying hamstring curl if seated equipment is unavailable.'},
  {id:'calfstand',name:'Standing calf raise',sets:3,target:'10–12',qtyUnit:'reps',rest:90,tempo:'3–1–2',how:'Lower heels for three seconds, pause briefly, then rise onto the balls of your feet. Use a comfortable range.',watch:'Do not bounce or force the heel stretch; avoid equipment placing pressure on the neck.',modify:'Single-leg supported calf raise with light weight.'},
  {id:'deadbug',name:'Dead bug',sets:2,target:'8 / side',qtyUnit:'reps/side',rest:60,tempo:'slow',how:'Lie on your back with hips and knees bent. Extend opposite arm and leg while bracing gently, then return.',watch:'Relax your head. Keep the lower back from arching.',modify:'Shorten the leg extension or use heel taps.'}
 ],
 B: [
  {id:'dbrdl',name:'Dumbbell Romanian deadlift',sets:3,target:'8',qtyUnit:'reps',rest:150,tempo:'3–1–1',how:'Soften knees, push hips back, and lower dumbbells close to legs. Stop at your controlled hamstring range, then stand tall.',watch:'Maintain a neutral neck and spine; never force the weights to the floor. Keep early sets extra light if back-sensitive.',modify:'Hip thrust or floor glute bridge.'},
  {id:'latpull',name:'Neutral-grip lat pulldown',sets:3,target:'8–12',qtyUnit:'reps',rest:120,tempo:'2–1–2',how:'With torso upright, pull handles toward upper chest, guiding elbows down toward ribs; return slowly.',watch:'Do not pull behind the neck, thrust your chin forward, or swing backward.',modify:'Assisted pullup with neutral grip or chest-supported row.'},
  {id:'dbshoulder',name:'Supported DB shoulder press',sets:2,target:'8–10',qtyUnit:'reps',rest:120,tempo:'2–0–2',how:'Sit against a backrest, palms facing in, and press overhead only through a comfortable range.',watch:'No neck pain, chin jutting, or excessive low-back arch.',modify:'Landmine press or inclined chest press if overhead lifting provokes symptoms.'},
  {id:'legpress',name:'Leg press',sets:2,target:'10–12',qtyUnit:'reps',rest:120,tempo:'3–1–1',how:'Keep hips and back supported. Lower to a depth where the pelvis stays on the pad; press through your whole foot.',watch:'Avoid knees collapsing inward, hips lifting, or aggressively locking knees.',modify:'Supported squat or step-up.'},
  {id:'calfseat',name:'Seated calf raise',sets:3,target:'12–15',qtyUnit:'reps',rest:90,tempo:'3–1–2',how:'With bent knees, lower heels slowly, pause, and rise smoothly.',watch:'No bouncing or painful stretching of the Achilles tendon.',modify:'Bent-knee supported calf raise.'},
  {id:'pallof',name:'Pallof press',sets:2,target:'10 / side',qtyUnit:'reps/side',rest:60,tempo:'2-sec hold',how:'Stand sideways to a cable. Press hands forward, resist rotation for two seconds, then return.',watch:'No shrugging, twisting, or rib flare.',modify:'Lighter resistance band anti-rotation hold.'}
 ],
 C: [
  {id:'split',name:'Supported split squat',sets:3,target:'8 / leg',qtyUnit:'reps/leg',rest:120,tempo:'3–1–1',how:'Use a rack for balance. Lower straight down in a staggered stance, maintaining full front-foot contact.',watch:'Avoid knee collapse, twisting, or neck strain.',modify:'Bodyweight split squat, assisted step-up, or leg press.'},
  {id:'incline',name:'Low-incline DB bench press',sets:3,target:'8–10',qtyUnit:'reps',rest:120,tempo:'2–1–1',how:'Set bench to 15–30°. Keep head supported and press with a comfortable neutral or semi-neutral grip.',watch:'Do not lift head, overarch the back, or push through shoulder pain.',modify:'Chest press machine.'},
  {id:'cablerow',name:'Seated cable row',sets:3,target:'10–12',qtyUnit:'reps',rest:90,tempo:'2–1–2',how:'Sit tall, pull handles to lower ribs, pause, and return slowly without leaning excessively.',watch:'No chin jutting, twisting, or momentum.',modify:'Chest-supported row machine.'},
  {id:'hipthrust',name:'Hip thrust',sets:2,target:'10–12',qtyUnit:'reps',rest:105,tempo:'2–2–2',how:'With shoulders supported and feet planted, lift hips until trunk and thighs form a line. Squeeze glutes, then descend.',watch:'Do not hyperextend your lower back or throw head back.',modify:'Floor glute bridge.'},
  {id:'lateral',name:'Cable lateral raise',sets:2,target:'12–15',qtyUnit:'reps/arm',rest:60,tempo:'2–1–2',how:'With slight elbow bend, raise arm to near shoulder height; lower with control.',watch:'Keep shoulders relaxed, no shrugging or neck tightening.',modify:'Light dumbbell lateral raise or omit if symptomatic.'},
  {id:'carry',name:'Farmer carry',sets:2,target:'20–30 m',qtyUnit:'meters',rest:105,tempo:'controlled walk',how:'Walk tall carrying moderate weights at your sides. Keep ribs stacked, shoulders relaxed, and steps controlled.',watch:'Stop if shoulders shrug, neck tightens, back leans, or grip fails.',modify:'Use lighter weights, shorter distance, or skip until assessed if neck symptoms recur.'},
  {id:'birddog',name:'Bird dog',sets:2,target:'6 / side',qtyUnit:'reps/side',rest:45,tempo:'3–5-sec hold',how:'On hands and knees, extend opposite arm and leg with gentle bracing; hold briefly and return.',watch:'Keep gaze down, hips level, and lower back steady.',modify:'Extend one limb at a time.'}
 ]
};
const EXTRAS = [
 {id:'wallsit',name:'Optional wall sit hold',sets:2,target:'20–40 sec',qtyUnit:'seconds',rest:75,tempo:'isometric',how:'With back against a wall and feet in front, lower to a comfortable knee angle and hold steadily.',watch:'No sharp knee pain or breath-holding.',modify:'Shallower knee bend or omit.'},
 {id:'calfhold',name:'Optional calf raise hold',sets:2,target:'20–40 sec',qtyUnit:'seconds',rest:75,tempo:'isometric',how:'With support for balance, rise into a comfortable mid-range calf position and hold.',watch:'Avoid sharp Achilles pain, bouncing, or cramping.',modify:'Two-legged supported hold with less effort.'}
];
const NAMES = {A:'Squat + Upper Body',B:'Posterior Chain + Pull',C:'Unilateral + Stability'};
const SUBTITLES = {A:'Squat · Press · Row · Calves · Core',B:'Hinge · Pull · Press · Quads · Core',C:'Single leg · Press · Row · Carries'};
const main = document.getElementById('main');
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const addDays = (s,n) => {const [y,m,d]=s.split('-').map(Number);return localDate(new Date(y,m-1,d+n));};
const dayDiff = (start,end) => {const a=new Date(`${start}T12:00:00`),b=new Date(`${end}T12:00:00`);return Math.round((b-a)/86400000)};
const monday = s => {const d=new Date(`${s}T12:00:00`);return addDays(s,-((d.getDay()+6)%7));};
const clamp=(n,lo,hi)=>Math.min(hi,Math.max(lo,n));
const readSettings=()=>{try{return JSON.parse(localStorage.getItem('stronger_settings'))||{}}catch{return {}}};
const settings={startDate:monday(localDate()),theme:'dark',...readSettings()};
const state={tab:'workout',date:localDate(),week:1,day:'A',sessions:[],current:null,historyQuery:'',historyWeek:'all',insightExercise:'goblet',dirty:false,saveTimer:null,db:null,storeMode:'indexeddb',timerEnd:0,timerLabel:'',timerTicker:null,expanded:{}};
function weekForDate(date){return clamp(Math.floor(dayDiff(settings.startDate,date)/7)+1,1,12)}
state.week=weekForDate(state.date);
function saveSettings(){try{localStorage.setItem('stronger_settings',JSON.stringify(settings))}catch{toast('Cannot save settings: storage is restricted')}}
async function initStorage(){
 try{if(!('indexedDB'in window))throw Error('IndexedDB missing');state.db=await new Promise((resolve,reject)=>{let r=indexedDB.open('stronger_workout_log',1);r.onupgradeneeded=()=>r.result.createObjectStore('sessions',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('DB blocked'))});
 state.sessions=await new Promise((resolve,reject)=>{const t=state.db.transaction('sessions','readonly'),r=t.objectStore('sessions').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)});
 }catch(e){state.storeMode='localStorage';try{state.sessions=JSON.parse(localStorage.getItem('stronger_sessions')||'[]')}catch{state.sessions=[]}}
}
async function dbPut(session){if(state.storeMode==='localStorage'){try{localStorage.setItem('stronger_sessions',JSON.stringify(state.sessions));return}catch(e){toast('Storage full or restricted — export a backup!');throw e}}
 return new Promise((resolve,reject)=>{const tx=state.db.transaction('sessions','readwrite');tx.objectStore('sessions').put(session);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});
}
async function dbRemove(id){if(state.storeMode==='localStorage'){localStorage.setItem('stronger_sessions',JSON.stringify(state.sessions));return}
 return new Promise((resolve,reject)=>{const tx=state.db.transaction('sessions','readwrite');tx.objectStore('sessions').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});
}
async function dbReplace(sessions){if(state.storeMode==='localStorage'){localStorage.setItem('stronger_sessions',JSON.stringify(sessions));return}
 return new Promise((resolve,reject)=>{const tx=state.db.transaction('sessions','readwrite');const store=tx.objectStore('sessions');store.clear();sessions.forEach(s=>store.put(s));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});
}
function setsFor(ex,week){const n=week===4||week===8?Math.max(1,Math.ceil(ex.sets*.5)):ex.sets;return Array.from({length:n},()=>({weight:'',qty:'',rpe:'',done:false}));}
function makeSession(date,day,week){return {id:`${date}|${day}`,date,day,week,exercises:LIBRARY[day].map(ex=>({...ex,setsData:setsFor(ex,week)})),notes:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),completedAt:null};}
function chooseCurrent(){const id=`${state.date}|${state.day}`;state.current=state.sessions.find(s=>s.id===id)||makeSession(state.date,state.day,state.week);if(state.current.week)state.week=state.current.week;}
function isExerciseValid(ex){return ex && typeof ex.name==='string' && Array.isArray(ex.setsData)}
function storeCurrent(){const session=state.current;if(!session)return Promise.resolve();session.updatedAt=new Date().toISOString();const idx=state.sessions.findIndex(s=>s.id===session.id);if(idx>=0)state.sessions[idx]=session;else state.sessions.push(session);state.dirty=false;return dbPut(structuredClone(session)).then(()=>{const out=$('savestate');if(out)out.textContent='Saved on this iPhone · '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}).catch(()=>toast('Save failed — export a backup'))}
function queueSave(){state.dirty=true;const out=$('savestate');if(out)out.textContent='Saving locally…';clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>storeCurrent(),250)}
async function flush(){clearTimeout(state.saveTimer);if(state.dirty)await storeCurrent()}
function getPhase(w){if(w===4||w===8)return 'Deload';if(w<=3)return 'Foundation';if(w<=7)return 'Build';if(w<=11)return 'Strength';return 'Assessment'}
function rpeTarget(week,i){const phase=(week===4||week===8)?[5,5.5,6]:week<=3?[5.5,6,7]:week<=7?[6,7,8]:week<=11?[6.5,7.5,8.5]:[6,7,8];return phase[Math.min(i,phase.length-1)]}
function targetFor(ex,week,i){if(ex.tempo==='isometric')return `RPE ${rpeTarget(week,i)}`;return `RPE ${rpeTarget(week,i)}`}
function countDone(s){return (s?.exercises||[]).reduce((n,ex)=>n+(ex.setsData||[]).filter(set=>set.done).length,0)}
function countSets(s){return (s?.exercises||[]).reduce((n,ex)=>n+(ex.setsData||[]).length,0)}
const safeNumber=v=>v===''||v==null?null:Number.isFinite(Number(v))?Number(v):null;
function totalVolume(s){return (s.exercises||[]).reduce((sum,ex)=>sum+(ex.setsData||[]).reduce((n,set)=>{const w=safeNumber(set.weight),q=safeNumber(set.qty);return n+(set.done && ['reps','reps/side','reps/leg','reps/arm'].includes(ex.qtyUnit)&&w!=null&&q!=null ? w*q : 0)},0),0)}
function toast(str){const el=$('toast');el.textContent=str;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),2600)}
function formatDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return s||'';const [y,m,d]=s.split('-');return new Date(+y,+m-1,+d).toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'})}
function updateConnection(){const online=navigator.onLine;const cached=('serviceWorker'in navigator)&&!!navigator.serviceWorker.controller;const label=online?(cached?'Offline ready':'Local saving'):'Working offline';$('connection').innerHTML=`<span class="statusdot" style="background:${online?'var(--accent)':'var(--accent2)'}"></span>${label}`;}
function navbar(){document.querySelectorAll('.navbtn').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false')})}
function render(){navbar();document.body.classList.toggle('app-light',settings.theme==='light');if(state.tab==='workout')renderWorkout();if(state.tab==='history')renderHistory();if(state.tab==='insights')renderInsights();if(state.tab==='settings')renderSettings();}
function inputSet(ex,i,set){const target=targetFor(ex,state.current.week,i),unit=ex.qtyUnit||'reps';return `<div class="set-grid ${set.done?'completed':''}" data-set-row="${esc(ex.id)}-${i}">
 <div class="set-number">${i+1}<div class="hint">${esc(target.replace('RPE ',''))}</div></div>
 <input type="number" inputmode="decimal" min="0" max="100000" step="0.5" aria-label="${esc(ex.name)} set ${i+1} weight in pounds" placeholder="lb" data-set-field="weight" data-ex="${esc(ex.id)}" data-i="${i}" value="${esc(set.weight)}">
 <input type="number" inputmode="decimal" min="0" max="100000" step="1" aria-label="${esc(ex.name)} set ${i+1} ${esc(unit)}" placeholder="${esc(unit==='meters'?'m':unit==='seconds'?'sec':'reps')}" data-set-field="qty" data-ex="${esc(ex.id)}" data-i="${i}" value="${esc(set.qty)}">
 <input type="number" inputmode="decimal" min="1" max="10" step="0.5" aria-label="${esc(ex.name)} set ${i+1} RPE" placeholder="RPE" data-set-field="rpe" data-ex="${esc(ex.id)}" data-i="${i}" value="${esc(set.rpe)}">
 <input type="checkbox" class="setdone" aria-label="Mark ${esc(ex.name)} set ${i+1} complete" data-set-field="done" data-ex="${esc(ex.id)}" data-i="${i}" ${set.done?'checked':''}>
 </div>`}
function exerciseHTML(ex,index){const open=!!state.expanded[ex.id];const unit=(ex.qtyUnit||'reps');return `<article class="exercise">
 <div class="exercise-head"><div class="row"><div class="row" style="justify-content:flex-start;min-width:0"><span class="ex-idx">${index+1}</span><div><div class="ex-name">${esc(ex.name)}</div><div class="ex-prescription">${ex.setsData.length} sets × ${esc(ex.target)} · ${Math.round(ex.rest/60*10)/10} min rest · ${esc(ex.tempo)}</div></div></div><div class="ex-tools"><button class="iconbtn" data-action="toggle-ex" data-ex="${esc(ex.id)}" aria-label="${open?'Hide':'Show'} technique for ${esc(ex.name)}">${open?'−':'ⓘ'}</button></div></div></div>
 <div class="set-grid" style="padding-top:0;padding-bottom:3px"><span class="set-label">Set / target</span><span class="set-label">Load (lb)</span><span class="set-label">${unit==='meters'?'Distance':unit==='seconds'?'Seconds':'Reps / qty'}</span><span class="set-label">RPE</span><span class="set-label">✓</span></div>
 ${(ex.setsData||[]).map((set,i)=>inputSet(ex,i,set)).join('')}
 <div class="exercise-footer"><button class="tiny-button" data-action="toggle-ex" data-ex="${esc(ex.id)}">${open?'Hide technique':'How to + precautions'}</button><div class="buttonrow"><button class="button secondary smallbtn" data-action="rest" data-rest="${ex.rest}" data-ex="${esc(ex.id)}">◷ Rest ${timeLabel(ex.rest)}</button>${ex.custom?`<button class="iconbtn" data-action="remove-custom" data-ex="${esc(ex.id)}" aria-label="Remove custom exercise">×</button>`:''}</div></div>
 ${open?`<div class="details"><b>Technique</b><p>${esc(ex.how)}</p><b>Watch for</b><p>${esc(ex.watch)}</p><b>Alternative</b><p>${esc(ex.modify)}</p><span class="planpill">Target: ${esc(ex.target)} · ${esc(targetFor(ex,state.current.week,Math.max(0,ex.setsData.length-1)))}</span></div>`:''}</article>`}
function timeLabel(sec){return sec>=60?`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`:`${sec}s`}
function renderWorkout(){if(!state.current)chooseCurrent();const s=state.current,done=countDone(s),total=countSets(s),pct=total?Math.round(done/total*100):0;main.innerHTML=`<div class="eyebrow">12-week training program · ${esc(getPhase(s.week))}</div>
 <div class="hero"><div class="row"><span class="tag">WEEK ${s.week} / 12</span><span class="tag">${s.completedAt?'✓ Completed':'In progress'}</span></div><h1>Day ${s.day} <span class="accent">/</span> ${esc(NAMES[s.day]||'Workout')}</h1><p>${esc(SUBTITLES[s.day]||'Strength and stability')}</p><div class="hero-tags"><span class="tag">${s.exercises.length} exercises</span><span class="tag">${total} working sets</span><span class="tag">Controlled strength</span></div></div>
 <div class="day-switch">${['A','B','C'].map(d=>`<button data-action="pick-day" data-day="${d}" class="${s.day===d?'active':''}">DAY ${d}</button>`).join('')}</div>
 <div class="panel"><div class="controls"><div class="field"><label for="workoutDate">Workout date</label><input id="workoutDate" type="date" value="${esc(s.date)}"></div><div class="field"><label for="weekSelect">Training week</label><select id="weekSelect">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${s.week===i+1?'selected':''}>Week ${i+1} · ${esc(getPhase(i+1))}</option>`).join('')}</select></div></div>
 <div class="workout-meta"><span class="small muted" id="setcount">${done} / ${total} sets logged</span><span class="small accent" id="setpercent">${pct}%</span></div><div class="progressbar"><div id="progressfill" style="width:${pct}%"></div></div><div id="savestate" class="savedrow" style="margin-top:10px">${state.sessions.some(x=>x.id===s.id)?'Saved locally on this device':'New session · Auto-saves as you log'}</div></div>
 <div class="callout"><strong style="color:var(--text)">Your intensity rule:</strong> Most sets RPE 5–8, controlled form, no failure. If neck pain or radiating symptoms return, stop the provoking movement. <span class="accent">Tap ⓘ</span> on any exercise for technique.</div>
 <div class="row wrap"><h2 class="section-title" style="margin:10px 0">Today's exercises</h2><button class="button secondary smallbtn" data-action="add-ex">+ Add exercise</button></div>
 ${s.exercises.map((ex,i)=>exerciseHTML(ex,i)).join('')}
 <div class="panel"><div class="field"><label for="workoutNotes">Session notes · symptoms · recovery</label><textarea id="workoutNotes" placeholder="How did your neck/back feel? What went well?">${esc(s.notes||'')}</textarea></div><div class="row wrap" style="margin-top:13px"><button class="button secondary" data-action="save">Save draft</button><button class="button" data-action="finish">${s.completedAt?'Update completed workout':'Finish workout ✓'}</button></div><p class="footnote" style="margin-bottom:0">Every change saves locally, even without tapping Finish. Finish marks this session complete for your progress reports.</p></div>`;
}
function updateWorkoutSummary(){const s=state.current,done=countDone(s),total=countSets(s),pct=total?Math.round(done/total*100):0;if($('setcount'))$('setcount').textContent=`${done} / ${total} sets logged`;if($('setpercent'))$('setpercent').textContent=`${pct}%`;if($('progressfill'))$('progressfill').style.width=`${pct}%`}
function renderHistory(){const total=state.sessions.filter(s=>s.completedAt).length;main.innerHTML=`<div class="eyebrow">Your training archive</div><h1 class="pagetitle">Workout history</h1><p class="subtitle">Every session stays on this device and is available without internet. Reopen any day to edit it.</p>
 <div class="summarycards"><div class="stat"><div class="value">${total}</div><div class="key">Finished workouts</div></div><div class="stat"><div class="value">${state.sessions.length}</div><div class="key">Saved sessions</div></div><div class="stat"><div class="value">${state.sessions.reduce((a,s)=>a+countDone(s),0)}</div><div class="key">Completed sets</div></div></div>
 <div class="panel" style="margin-top:15px"><div class="history-filters"><div class="field"><label for="searchHistory">Find a workout</label><input id="searchHistory" value="${esc(state.historyQuery)}" placeholder="Exercise, date, notes…"></div><div class="field"><label for="filterWeek">Week</label><select id="filterWeek"><option value="all">All weeks</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(state.historyWeek)===String(i+1)?'selected':''}>Week ${i+1}</option>`).join('')}</select></div></div></div>
 <div id="historyList"></div><div class="buttonrow" style="margin-top:16px"><button class="button secondary" data-action="csv-export">Export spreadsheet CSV</button><button class="button secondary" data-action="json-export">Back up all data</button></div>`;updateHistoryList()}
function updateHistoryList(){const q=state.historyQuery.trim().toLowerCase();const filtered=state.sessions.filter(s=>(state.historyWeek==='all'||String(s.week)===String(state.historyWeek))&&(!q||[s.date,`day ${s.day}`,s.notes,...s.exercises.map(ex=>ex.name)].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt));const list=$('historyList');if(!list)return;list.innerHTML=filtered.length?filtered.map(s=>`<article class="record"><div class="row"><div><div class="row" style="justify-content:flex-start;gap:8px"><strong>Day ${esc(s.day)} · ${esc(formatDate(s.date))}</strong><span class="badge ${s.completedAt?'success':''}">${s.completedAt?'Completed':'Draft'}</span></div><div class="meta">Week ${s.week} · ${countDone(s)} / ${countSets(s)} sets · ${esc(NAMES[s.day]||'Workout')}</div>${s.notes?`<div class="meta">${esc(s.notes.slice(0,120))}${s.notes.length>120?'…':''}</div>`:''}</div></div><div class="buttonrow" style="margin-top:11px"><button class="button secondary smallbtn" data-action="edit-session" data-id="${esc(s.id)}">View / Edit</button><button class="button ghost smallbtn" data-action="details-session" data-id="${esc(s.id)}">Set details</button><button class="button danger smallbtn" data-action="delete-session" data-id="${esc(s.id)}">Delete</button></div></article>`).join(''):`<div class="empty"><span class="big">▤</span>No workouts match your filters.<br>Log your first workout from the Workout tab.</div>`}
function historyDetails(id){const s=state.sessions.find(s=>s.id===id);if(!s)return;openModal(`<h2>Day ${esc(s.day)} · ${esc(formatDate(s.date))}</h2><p class="subtitle">Week ${s.week} · ${esc(s.completedAt?'Completed':'Draft')}</p><div style="overflow:auto"><table class="simpletable"><thead><tr><th>Exercise / set</th><th>Load</th><th>Qty</th><th>RPE</th><th>✓</th></tr></thead><tbody>${s.exercises.map(ex=>ex.setsData.map((x,i)=>`<tr><td>${esc(ex.name)} · ${i+1}</td><td>${esc(x.weight||'—')}</td><td>${esc(x.qty||'—')}</td><td>${esc(x.rpe||'—')}</td><td>${x.done?'✓':'—'}</td></tr>`).join('')).join('')}</tbody></table></div><p class="helptext">${esc(s.notes||'No notes recorded.')}</p><div class="modalactions"><button class="button secondary" data-action="close-modal">Close</button><button class="button" data-action="edit-session" data-id="${esc(s.id)}">Edit workout</button></div>`)}
function renderInsights(){const completed=state.sessions.filter(s=>s.completedAt);const days=[...new Set(completed.map(s=>s.date))].length;const unique=[...new Map([...LIBRARY.A,...LIBRARY.B,...LIBRARY.C,...EXTRAS].map(ex=>[ex.id,ex])).values()];const extras=state.sessions.flatMap(s=>s.exercises).filter(ex=>!unique.some(e=>e.id===ex.id));const all=[...unique,...new Map(extras.map(ex=>[ex.id,ex])).values()];main.innerHTML=`<div class="eyebrow">Track improvement, not just weight</div><h1 class="pagetitle">Your progress</h1><p class="subtitle">Your history and charts are calculated from workout records saved locally on this device.</p>
 <div class="summarycards"><div class="stat"><div class="value">${completed.length}</div><div class="key">Completed sessions</div></div><div class="stat"><div class="value">${days}</div><div class="key">Training days</div></div><div class="stat"><div class="value">${state.sessions.reduce((n,s)=>n+countDone(s),0)}</div><div class="key">Logged sets</div></div></div>
 <div class="panel" style="margin-top:16px"><div class="field"><label for="insightExercise">Exercise to review</label><select id="insightExercise">${all.map(ex=>`<option value="${esc(ex.id)}" ${ex.id===state.insightExercise?'selected':''}>${esc(ex.name)}</option>`).join('')}</select></div><div id="exerciseChart"></div></div>
 <h2 class="section-title">12-week consistency</h2><div class="panel"><div class="small muted" style="margin-bottom:12px">Completed sessions per training week (goal: 3)</div><div style="display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:5px;align-items:end;height:117px">${Array.from({length:12},(_,i)=>{const c=completed.filter(s=>s.week===i+1).length;return `<div style="display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:5px"><span class="tiny muted">${c||''}</span><div style="width:100%;height:${Math.max(5,Math.min(3,c)/3*76)}px;background:${c?'var(--accent)':'var(--surface3)'};border-radius:5px 5px 2px 2px"></div><span class="tiny muted">${i+1}</span></div>`}).join('')}</div></div>
 <h2 class="section-title">Recent best working sets</h2><div class="panel" id="bestSetTable"></div><div class="buttonrow"><button class="button secondary" data-action="csv-export">Open in Numbers / Excel (CSV)</button></div><p class="footnote">Charts use the heaviest completed working set per session, not an estimated one-rep maximum. Exercise progress should be evaluated alongside reps, RPE, technique, and symptoms.</p>`;renderChart();renderBestSets()}
function recordsForExercise(id){return state.sessions.flatMap(s=>s.exercises.filter(ex=>ex.id===id).flatMap(ex=>ex.setsData.filter(set=>set.done).map(set=>({date:s.date,weight:safeNumber(set.weight),qty:safeNumber(set.qty),rpe:safeNumber(set.rpe),unit:ex.qtyUnit,completed:!!s.completedAt})))).filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date))}
function renderChart(){const el=$('exerciseChart');if(!el)return;
 const all=[];
 state.sessions.forEach(s=>s.exercises.filter(ex=>ex.id===state.insightExercise).forEach(ex=>ex.setsData.forEach(set=>{
  if(set.done && set.weight!=='' && safeNumber(set.weight)!==null) all.push({date:s.date,weight:Number(set.weight),qty:set.qty,rpe:set.rpe});
 })));
 const byDate=new Map();all.forEach(p=>{if(!byDate.has(p.date)||p.weight>byDate.get(p.date).weight)byDate.set(p.date,p)});const data=[...byDate.values()].sort((a,b)=>a.date.localeCompare(b.date));if(!data.length){el.innerHTML='<div class="empty" style="margin-top:16px">No completed sets with a recorded weight yet. Log some sets to create this chart.</div>';return}const max=Math.max(1,...data.map(x=>x.weight)),min=Math.min(0,...data.map(x=>x.weight));const W=550,H=205,l=48,r=15,t=24,b=39;const x=i=>data.length===1?(W-l-r)/2+l:l+(W-l-r)*(i/(data.length-1));const y=v=>t+(H-t-b)*(1-(v-min)/(max-min||1));const points=data.map((p,i)=>`${x(i)},${y(p.weight)}`).join(' ');const path=data.map((p,i)=>`${i?'L':'M'}${x(i)} ${y(p.weight)}`).join(' ');const guides=[0,.5,1].map(ratio=>{const v=min+(max-min)*ratio;return `<line class="chartgrid" x1="${l}" y1="${y(v)}" x2="${W-r}" y2="${y(v)}"/><text class="chartlabel" text-anchor="end" x="${l-8}" y="${y(v)+4}">${Math.round(v)} lb</text>`}).join('');el.innerHTML=`<div class="row" style="margin-top:20px"><div><div class="eyebrow">Heaviest logged working set</div><div style="font-size:28px;font-weight:900;margin-top:4px">${Number(data[data.length-1].weight).toLocaleString()} <span class="muted" style="font-size:13px">lb latest</span></div></div><span class="badge">${data.length} dates</span></div><svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Weight progress by date"><g>${guides}</g><path d="${path}" stroke="var(--accent)" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>${data.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.weight)}" r="4.5" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"><title>${esc(formatDate(p.date))}: ${p.weight} lb, ${esc(p.qty)} reps, RPE ${esc(p.rpe)}</title></circle>`).join('')}<text class="chartlabel" x="${l}" y="${H-8}">${esc(formatDate(data[0].date))}</text><text class="chartlabel" text-anchor="end" x="${W-r}" y="${H-8}">${esc(formatDate(data[data.length-1].date))}</text></svg><p class="helptext">${data.length===1?'Log another date to see a trend.':'Trend shows load only; remember to compare repetitions and RPE as well.'}</p>`}
function renderBestSets(){const el=$('bestSetTable');if(!el)return;const best=new Map();state.sessions.forEach(s=>s.exercises.forEach(ex=>ex.setsData.forEach(set=>{const w=safeNumber(set.weight);if(!set.done||w===null||!w)return;const current=best.get(ex.name);if(!current||w>current.weight)best.set(ex.name,{name:ex.name,weight:w,qty:set.qty,date:s.date})})));const arr=[...best.values()].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);el.innerHTML=arr.length?`<table class="simpletable"><thead><tr><th>Exercise</th><th>Load</th><th>Date</th></tr></thead><tbody>${arr.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.weight} lb${p.qty?' × '+esc(p.qty):''}</td><td>${esc(formatDate(p.date))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Complete and log sets to see your best loads.</div>'}
function renderSettings(){main.innerHTML=`<div class="eyebrow">Local-first · private by design</div><h1 class="pagetitle">Settings & data</h1><p class="subtitle">Your training history is stored on this device. It does not require an account or internet after the app is installed.</p>
 <div class="panel"><div class="settingsitem"><b>Program start date</b><p>Used to suggest your 12-week training week when choosing a workout date. You can still override any workout's week.</p><div class="field"><input type="date" id="startDate" value="${esc(settings.startDate)}"></div></div>
 <div class="settingsitem"><b>Appearance</b><div class="buttonrow"><button class="button ${settings.theme==='dark'?'':'secondary'} smallbtn" data-action="theme" data-value="dark">Dark</button><button class="button ${settings.theme==='light'?'':'secondary'} smallbtn" data-action="theme" data-value="light">Light</button></div></div>
 <div class="settingsitem"><b>Export as a spreadsheet</b><p>Download a CSV file with one row per exercise set: date, day, week, weight, reps, RPE, completion status, and notes. Opens in Apple Numbers, Microsoft Excel, and Google Sheets.</p><button class="button" data-action="csv-export">⇩ Export CSV</button></div>
 <div class="settingsitem"><b>Complete backup (recommended)</b><p>Download a JSON backup that preserves every workout, including custom exercises and settings. Store it in iCloud Drive or Files. Import it if you reinstall or change phones.</p><div class="buttonrow"><button class="button secondary" data-action="json-export">⇩ Export backup</button><button class="button secondary" data-action="import-json">⇧ Restore backup</button></div></div>
 <div class="settingsitem"><b>Import spreadsheet CSV</b><p>Re-import CSV files previously exported from this app. Matching date + day sessions will be overwritten, so export a backup first.</p><button class="button secondary" data-action="import-csv">⇧ Import CSV</button></div>
 <div class="settingsitem"><b>Local storage</b><p>${state.sessions.length} saved sessions. Storage engine: ${esc(state.storeMode)}. Data stays on this device; clearing website data, deleting the home-screen app, or iOS storage cleanup may erase it.</p><p class="settingsnotice">There is no automatic cloud backup or device sync. Export a JSON backup regularly.</p><button class="button danger smallbtn" data-action="erase-all">Erase all workout history</button></div></div>
 <div class="panel"><b>Install on iPhone (one-time internet)</b><ol class="helptext" style="padding-left:19px"><li>Upload the app's files to an HTTPS website such as GitHub Pages.</li><li>Open that website using <b>Safari</b> on your iPhone.</li><li>Tap Share → <b>Add to Home Screen</b> → Add (on newer iOS versions, find Add to Home Screen under Share).</li><li>Launch the new Stronger icon once while online. Then you can use your workouts offline.</li></ol><p class="helptext">If you change the hosted files, open the site once with internet to fetch an updated version.</p></div>
 <p class="footnote">Medical note: this is a strength-training journal, not medical advice or a diagnosis. The past neck injury should be fully recovered before loaded exercise.</p>`}
function openModal(html){$('modalroot').innerHTML=`<div class="modalbackdrop" id="backdrop"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;document.body.style.overflow='hidden'}
function closeModal(){$('modalroot').innerHTML='';document.body.style.overflow=''}
function addExerciseModal(){const options=[...EXTRAS,...LIBRARY.A,...LIBRARY.B,...LIBRARY.C].filter((e,i,arr)=>arr.findIndex(y=>y.id===e.id)===i&&!state.current.exercises.some(x=>x.id===e.id));openModal(`<h2>Add an exercise</h2><p class="subtitle">Optional tendon holds or any custom movement. Added to this workout only.</p><div class="field"><label for="presets">Choose from library</label><select id="presets"><option value="custom">Custom exercise…</option>${options.map(ex=>`<option value="${esc(ex.id)}">${esc(ex.name)}</option>`).join('')}</select></div><div id="customfields"><div class="field"><label for="customName">Exercise name</label><input id="customName" maxlength="85" placeholder="e.g. Face pull"></div><div class="controls"><div class="field"><label for="customSets">Sets</label><input id="customSets" type="number" min="1" max="8" value="2"></div><div class="field"><label for="customTarget">Target reps/qty</label><input id="customTarget" maxlength="25" value="10–12"></div></div><div class="controls"><div class="field"><label for="customRest">Rest seconds</label><input id="customRest" type="number" min="15" max="600" step="15" value="90"></div><div class="field"><label for="customUnit">Quantity unit</label><select id="customUnit"><option value="reps">Reps</option><option value="reps/side">Reps per side</option><option value="seconds">Seconds</option><option value="meters">Meters</option></select></div></div></div><div class="modalactions"><button class="button secondary" data-action="close-modal">Cancel</button><button class="button" data-action="confirm-add-ex">Add exercise</button></div>`)}
function addExercise(){const preset=$('presets').value;let ex;if(preset!=='custom'){ex=[...EXTRAS,...LIBRARY.A,...LIBRARY.B,...LIBRARY.C].find(x=>x.id===preset);if(!ex)return;ex=structuredClone(ex)}else{const name=$('customName').value.trim();if(!name){toast('Enter the exercise name');return}ex={id:'custom-'+Date.now(),name:name.slice(0,85),sets:clamp(Number($('customSets').value)||2,1,8),target:($('customTarget').value||'10–12').slice(0,25),qtyUnit:$('customUnit').value,rest:clamp(Number($('customRest').value)||90,15,600),tempo:'controlled',how:'Move under control within your comfortable range.',watch:'Avoid painful movements, neck strain, and form breakdown.',modify:'Use a lighter load, reduce range, or select a supported variation.',custom:true}}if(state.current.exercises.some(x=>x.id===ex.id)){toast('Exercise already added');return}ex.custom=true;ex.setsData=setsFor(ex,state.current.week);state.current.exercises.push(ex);queueSave();closeModal();renderWorkout();toast('Exercise added')}
function confirmFinish(){if(countDone(state.current)===0){toast('Tick at least one completed set first');return}state.current.completedAt=new Date().toISOString();queueSave();flush().then(()=>{renderWorkout();toast('Workout finished and saved offline ✓')})}
async function selectWorkout(date,day,week){await flush();state.date=date;state.day=day;state.week=week;chooseCurrent();renderWorkout();window.scrollTo({top:0,behavior:'instant'})}
function startTimer(sec,label){state.timerEnd=Date.now()+sec*1000;state.timerLabel=label;clearInterval(state.timerTicker);state.timerTicker=setInterval(updateTimer,250);updateTimer()}
function updateTimer(){const el=$('resttimer');if(!state.timerEnd){el.hidden=true;return}const remaining=Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000));el.hidden=false;el.innerHTML=`<div><div class="tiny">REST · ${esc(state.timerLabel)}</div><div class="timerbig">${timeLabel(remaining)}</div></div><button data-action="stop-timer">${remaining?'Skip':'Close'}</button>`;if(remaining===0){clearInterval(state.timerTicker);if(!updateTimer.fired){toast('Rest complete — next set when ready')}updateTimer.fired=true}else updateTimer.fired=false;}
function stopTimer(){state.timerEnd=0;clearInterval(state.timerTicker);$('resttimer').hidden=true}
function csvCell(value){let v=String(value??'');if(/^[=+@\-\t\r]/.test(v)&&isNaN(Number(v)))v="'"+v;return /[",\r\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
const CSV_KEYS=['session_id','date','week','day','completed_at','created_at','updated_at','exercise_id','exercise','exercise_order','set_number','target','quantity_unit','rest_seconds','tempo','weight_lb','quantity','rpe','done','notes','how','watch','modify','custom'];
function makeCSV(){const rows=[CSV_KEYS];state.sessions.sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>s.exercises.forEach((ex,j)=>ex.setsData.forEach((set,i)=>rows.push([s.id,s.date,s.week,s.day,s.completedAt||'',s.createdAt||'',s.updatedAt||'',ex.id,ex.name,j+1,i+1,ex.target||'',ex.qtyUnit||'reps',ex.rest||90,ex.tempo||'',set.weight,set.qty,set.rpe,set.done?'true':'false',s.notes||'',ex.how||'',ex.watch||'',ex.modify||'',ex.custom?'true':'false']))));return '\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')}
function downloadFile(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},2500);toast('Export prepared — save it to Files')}
function exportCSV(){downloadFile(`stronger-workout-log-${localDate()}.csv`,makeCSV(),'text/csv;charset=utf-8')}
function exportJSON(){const payload={format:'stronger-workout-backup',version:1,exportedAt:new Date().toISOString(),settings,sessions:state.sessions};downloadFile(`stronger-full-backup-${localDate()}.json`,JSON.stringify(payload,null,2),'application/json')}
function chooseImport(type){const input=document.createElement('input');input.type='file';input.accept=type==='json'?'application/json,.json':'.csv,text/csv';input.style.position='fixed';input.style.opacity='0';input.style.pointerEvents='none';document.body.appendChild(input);input.addEventListener('change',async()=>{if(input.files?.length){try{const file=input.files[0];if(file.size>15*1024*1024)throw Error('File is too large (15 MB limit)');const content=await file.text();await flush();if(type==='json')await importJSON(content);else await importCSV(content)}catch(e){toast(`Import failed: ${e.message}`)}}input.remove()},{once:true});input.click();setTimeout(()=>{if(!input.files?.length)input.remove()},120000)}
function normalizeSession(s){if(!s||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!['A','B','C'].includes(s.day)||!Array.isArray(s.exercises))return null;const date=s.date,day=s.day,week=clamp(Number(s.week)||1,1,12);return {id:`${date}|${day}`,date,day,week,createdAt:String(s.createdAt||new Date().toISOString()).slice(0,60),updatedAt:String(s.updatedAt||new Date().toISOString()).slice(0,60),completedAt:s.completedAt?String(s.completedAt).slice(0,60):null,notes:String(s.notes||'').slice(0,30000),exercises:s.exercises.slice(0,50).filter(isExerciseValid).map((ex,i)=>({id:String(ex.id||`import-${i}`).slice(0,100),name:String(ex.name).slice(0,100),target:String(ex.target||'').slice(0,40),qtyUnit:String(ex.qtyUnit||'reps').slice(0,25),rest:clamp(Number(ex.rest)||90,15,600),tempo:String(ex.tempo||'controlled').slice(0,50),how:String(ex.how||'').slice(0,1000),watch:String(ex.watch||'').slice(0,1000),modify:String(ex.modify||'').slice(0,1000),sets:clamp(Number(ex.sets)||ex.setsData.length,1,20),custom:!!ex.custom,setsData:ex.setsData.slice(0,25).map(set=>({weight:String(set.weight??'').slice(0,20),qty:String(set.qty??'').slice(0,20),rpe:String(set.rpe??'').slice(0,20),done:!!set.done}))}))}}
async function importJSON(content){const data=JSON.parse(content);if(data.format!=='stronger-workout-backup'||!Array.isArray(data.sessions))throw Error('Not a Stronger JSON backup');const valid=data.sessions.map(normalizeSession).filter(Boolean);if(valid.length!==data.sessions.length)throw Error('Some backup sessions are invalid');if(!confirm(`Restore ${valid.length} sessions? This REPLACES all existing workouts on this phone. Export a backup first if needed.`))return;await dbReplace(valid);state.sessions=valid;if(data.settings&&/^\d{4}-\d{2}-\d{2}$/.test(data.settings.startDate||''))settings.startDate=data.settings.startDate;if(data.settings&&['dark','light'].includes(data.settings.theme))settings.theme=data.settings.theme;saveSettings();chooseCurrent();render();toast(`${valid.length} sessions restored`)}
function parseCSV(csv){const out=[],row=[];let cell='',quoted=false;csv=csv.replace(/^\uFEFF/,'');for(let i=0;i<csv.length;i++){const c=csv[i];if(quoted){if(c==='"'&&csv[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&csv[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))out.push([...row]);row.length=0;cell=''}else cell+=c}if(quoted)throw Error('CSV has an unmatched quotation mark');row.push(cell);if(row.some(x=>x!==''))out.push(row);return out}
async function importCSV(content){const matrix=parseCSV(content);if(matrix.length<2)throw Error('CSV has no rows');const headers=matrix.shift();const required=['date','week','day','exercise','set_number','weight_lb','quantity','rpe','done'];if(required.some(k=>!headers.includes(k)))throw Error('CSV does not match this app’s export format');const map=new Map();for(const arr of matrix){const obj=Object.fromEntries(headers.map((h,i)=>[h,arr[i]??'']));const date=obj.date,day=obj.day;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!['A','B','C'].includes(day))continue;const id=`${date}|${day}`;let s=map.get(id);if(!s){s={id,date,day,week:clamp(Number(obj.week)||1,1,12),createdAt:obj.created_at||new Date().toISOString(),updatedAt:obj.updated_at||new Date().toISOString(),completedAt:obj.completed_at||null,notes:obj.notes||'',exercises:[]};map.set(id,s)}let ex=s.exercises.find(e=>e.id===(obj.exercise_id||obj.exercise));if(!ex){const lib=[...LIBRARY.A,...LIBRARY.B,...LIBRARY.C,...EXTRAS].find(e=>e.id===obj.exercise_id||e.name===obj.exercise);ex={...lib,id:obj.exercise_id||lib?.id||`custom-${s.exercises.length}`,name:obj.exercise||lib?.name||'Unknown exercise',sets:3,target:obj.target||lib?.target||'',qtyUnit:obj.quantity_unit||lib?.qtyUnit||'reps',rest:clamp(Number(obj.rest_seconds)||lib?.rest||90,15,600),tempo:obj.tempo||lib?.tempo||'controlled',how:obj.how||lib?.how||'',watch:obj.watch||lib?.watch||'',modify:obj.modify||lib?.modify||'',custom:obj.custom==='true',setsData:[]};s.exercises.push(ex)}const index=Number(obj.set_number)-1;if(index<0||index>24||!Number.isInteger(index))continue;while(ex.setsData.length<=index)ex.setsData.push({weight:'',qty:'',rpe:'',done:false});ex.setsData[index]={weight:obj.weight_lb||'',qty:obj.quantity||'',rpe:obj.rpe||'',done:obj.done==='true'||obj.done==='1'}}const incoming=[...map.values()].map(normalizeSession).filter(Boolean);if(!incoming.length)throw Error('No valid sessions found');if(!confirm(`Import ${incoming.length} sessions from CSV? Existing workouts with the SAME date + day will be replaced. Other workouts stay unchanged.`))return;const merged=new Map(state.sessions.map(s=>[s.id,s]));incoming.forEach(s=>merged.set(s.id,s));await dbReplace([...merged.values()]);state.sessions=[...merged.values()];chooseCurrent();render();toast(`${incoming.length} sessions imported from CSV`)}
async function eraseAll(){if(!confirm('Permanently erase EVERY workout saved on this phone? This cannot be undone without a backup.'))return;if(!confirm('Final confirmation: delete all workout history?'))return;await dbReplace([]);state.sessions=[];chooseCurrent();render();toast('Workout history erased')}
function handleSetEdit(el){const ex=state.current.exercises.find(x=>x.id===el.dataset.ex);const idx=Number(el.dataset.i);if(!ex||!ex.setsData[idx])return;const key=el.dataset.setField;const entry=ex.setsData[idx];if(key==='done'){entry.done=el.checked;el.closest('.set-grid').classList.toggle('completed',entry.done)}else{const v=el.value;entry[key]=v;if(v!==''&&Number(v)<0){entry[key]='0';el.value='0'}if(key==='rpe'&&v!==''&&Number(v)>10){entry[key]='10';el.value='10'}}queueSave();updateWorkoutSummary()}
async function handleAction(btn){const action=btn.dataset.action;if(action==='pick-day')return selectWorkout(state.date,btn.dataset.day,state.week);
 if(action==='toggle-ex'){state.expanded[btn.dataset.ex]=!state.expanded[btn.dataset.ex];renderWorkout();return}
 if(action==='rest'){const ex=state.current.exercises.find(x=>x.id===btn.dataset.ex);startTimer(Number(btn.dataset.rest),ex?.name||'Between sets');return}
 if(action==='stop-timer')return stopTimer();
 if(action==='save'){await flush();if(!state.sessions.some(s=>s.id===state.current.id))await storeCurrent();toast('Workout saved on this device');return}
 if(action==='finish')return confirmFinish();
 if(action==='add-ex')return addExerciseModal();
 if(action==='close-modal')return closeModal();
 if(action==='confirm-add-ex')return addExercise();
 if(action==='remove-custom'){const ex=state.current.exercises.find(x=>x.id===btn.dataset.ex);if(ex?.custom&&confirm(`Remove ${ex.name} and its set data from this workout?`)){state.current.exercises=state.current.exercises.filter(x=>x.id!==ex.id);queueSave();renderWorkout()}return}
 if(action==='edit-session'){const s=state.sessions.find(s=>s.id===btn.dataset.id);if(!s)return;closeModal();state.tab='workout';navbar();return selectWorkout(s.date,s.day,s.week)}
 if(action==='details-session')return historyDetails(btn.dataset.id);
 if(action==='delete-session'){const s=state.sessions.find(s=>s.id===btn.dataset.id);if(!s||!confirm(`Delete Day ${s.day} on ${formatDate(s.date)}? This cannot be undone without a backup.`))return;state.sessions=state.sessions.filter(x=>x.id!==s.id);await dbRemove(s.id);if(state.current?.id===s.id)chooseCurrent();renderHistory();toast('Workout deleted');return}
 if(action==='csv-export')return exportCSV();
 if(action==='json-export')return exportJSON();
 if(action==='import-json')return chooseImport('json');
 if(action==='import-csv')return chooseImport('csv');
 if(action==='erase-all')return eraseAll();
 if(action==='theme'){settings.theme=btn.dataset.value;saveSettings();render();return}
}
document.addEventListener('click',async event=>{const nav=event.target.closest('[data-tab]');if(nav){await flush();state.tab=nav.dataset.tab;render();window.scrollTo({top:0,behavior:'instant'});return}const btn=event.target.closest('[data-action]');if(btn)try{await handleAction(btn)}catch(e){console.error(e);toast(`Action failed: ${e.message}`)}else if(event.target.id==='backdrop')closeModal()});
document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-set-field]:not([type=checkbox])'))handleSetEdit(el);if(el.id==='workoutNotes'){state.current.notes=el.value;queueSave()}if(el.id==='searchHistory'){state.historyQuery=el.value;updateHistoryList()}});
document.addEventListener('change',async event=>{const el=event.target;if(el.matches('[data-set-field][type=checkbox]'))return handleSetEdit(el);if(el.id==='workoutDate'){if(!el.value)return;return selectWorkout(el.value,state.day,weekForDate(el.value))}if(el.id==='weekSelect'){const w=Number(el.value);state.week=w;state.current.week=w;const hasValues=state.current.exercises.some(ex=>ex.setsData.some(set=>set.done||set.weight||set.qty||set.rpe));if(!hasValues)state.current.exercises.forEach(ex=>ex.setsData=setsFor(ex,w));queueSave();renderWorkout();if(hasValues)toast('Kept existing sets when changing weeks');return}if(el.id==='filterWeek'){state.historyWeek=el.value;return updateHistoryList()}if(el.id==='insightExercise'){state.insightExercise=el.value;return renderChart()}if(el.id==='startDate'){settings.startDate=el.value;saveSettings();toast('Program start date updated')}if(el.id==='presets'){const fields=$('customfields');if(fields)fields.style.display=el.value==='custom'?'block':'none'}});
window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);if('serviceWorker' in navigator)navigator.serviceWorker.addEventListener('controllerchange',updateConnection);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden' && state.dirty)storeCurrent()});
window.addEventListener('pagehide',()=>{if(state.dirty)storeCurrent()});
(async()=>{await initStorage();chooseCurrent();updateConnection();render();if('serviceWorker'in navigator && (location.protocol==='https:'||location.hostname==='localhost')){try{await navigator.serviceWorker.register('./sw.js',{scope:'./'})}catch(e){console.warn('Offline service worker unavailable',e)}}})();
